function computeSpectrum(e: PosEMLExpr, k: int) -> List[int]:
    spectrum = []
    current = e
    for i = 0 to k-1:
        spectrum.append(depth(current))
        current = certifiedDeriv(current)
        // Invariant: depth(current) <= depth(previous)
    return spectrum

function certifiedDeriv(e: PosEMLExpr) -> PosEMLExpr:
    match e with
    | const c => const 0
    | var     => const 1
    | add a b => add(certifiedDeriv(a), certifiedDeriv(b))
    | mul a b => add(mul(certifiedDeriv(a), b), mul(a, certifiedDeriv(b)))
    | exp a   => mul(certifiedDeriv(a), exp(a))
    // Certificate: depth(result) <= depth(e)
